#!/usr/bin/env bash
# Question 1: Ready, but one worker misbehaves. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q1_FAULT}" in
  kubelet-port-blocked)
    for _ in $(seq 1 30); do
      kubectl get --raw "/api/v1/nodes/${Q1_NODE}/proxy/healthz" >/dev/null 2>&1 || exit 0
      sleep 2
    done
    echo "the kubelet on ${Q1_NODE} still answers" >&2
    exit 1
    ;;
  cluster-dns-wrong)
    sleep 8
    kubectl -n "${Q1_NS}" delete pod -l app=fleet-check --field-selector "spec.nodeName=${Q1_NODE}" --wait=false >/dev/null
    for _ in $(seq 1 45); do
      [[ "$(kubectl -n "${Q1_NS}" get daemonset fleet-check -o jsonpath='{.status.numberReady}/{.status.desiredNumberScheduled}')" != 2/2 ]] && exit 0
      sleep 2
    done
    echo "fleet-check is still healthy on every worker" >&2
    exit 1
    ;;
  sandbox-image-wrong)
    sleep 8
    kubectl -n "${Q1_NS}" delete pod -l app=fleet-check --field-selector "spec.nodeName=${Q1_NODE}" --wait=false >/dev/null
    for _ in $(seq 1 45); do
      [[ "$(kubectl -n "${Q1_NS}" get daemonset fleet-check -o jsonpath='{.status.numberReady}/{.status.desiredNumberScheduled}')" != 2/2 ]] && exit 0
      sleep 2
    done
    echo "fleet-check is still healthy on every worker" >&2
    exit 1
    ;;
  cni-binary-missing)
    kubectl -n "${Q1_NS}" delete pod -l app=fleet-check --field-selector "spec.nodeName=${Q1_NODE}" --wait=false >/dev/null
    for _ in $(seq 1 45); do
      [[ "$(kubectl -n "${Q1_NS}" get daemonset fleet-check -o jsonpath='{.status.numberReady}/{.status.desiredNumberScheduled}')" != 2/2 ]] && exit 0
      sleep 2
    done
    echo "fleet-check is still healthy on every worker" >&2
    exit 1
    ;;
  overlay-blocked)
    for _ in $(seq 1 45); do
      [[ "$(kubectl -n "${Q1_NS}" get daemonset fleet-check -o jsonpath='{.status.numberReady}/{.status.desiredNumberScheduled}')" != 2/2 ]] && exit 0
      sleep 2
    done
    echo "fleet-check is still healthy on every worker" >&2
    exit 1
    ;;
  disk-full)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="DiskPressure")].status}')" == True ]] && exit 0
      sleep 2
    done
    echo "${Q1_NODE} never reported DiskPressure" >&2
    exit 1
    ;;
  node-object-deleted)
    for _ in $(seq 1 75); do
      [[ -z "$(kubectl -n "${Q1_NS}" get pods -l app=fleet-check --field-selector "spec.nodeName=${Q1_NODE}" -o name)" ]] && exit 0
      sleep 2
    done
    echo "the Pods of ${Q1_NODE} are still there" >&2
    exit 1
    ;;
esac
